-- One audited correction workspace in Reports; no new departmental edit actions.
begin;
do $$begin if public.get_technician_parts_report_version()is distinct from '20261029-technician-parts-1'then raise exception 'Verified Technician Parts Report is required.';end if;if to_regprocedure('public.get_full_imei_workflow_version()')is not null then if public.get_full_imei_workflow_version()is distinct from '20261029-full-imei-workflow-1'then raise exception 'Existing Full IMEI Workflow Correction needs review.';end if;end if;end;$$;
do $$declare u record;begin if not exists(select 1 from greenloop_private.page_capability_catalog where page_key='reports'and capabilities @> '[{"key":"workflow_correction"}]')then
 for u in select id,greenloop_private.user_capabilities(id)caps from public.user_profiles loop insert into greenloop_private.user_page_capabilities(user_id,capabilities)values(u.id,u.caps)on conflict(user_id)do nothing;end loop;
 update greenloop_private.page_capability_catalog set capabilities=capabilities||'[{"key":"workflow_correction","label":"Full IMEI Workflow Correction (Reports only)","write":true}]'where page_key='reports';
 update greenloop_private.user_page_capabilities c set capabilities=jsonb_set(capabilities,'{reports}',(capabilities->'reports')||'["workflow_correction"]')where capabilities->'reports'?'view'and exists(select 1 from public.user_roles ur join public.roles ro on ro.id=ur.role_id where ur.user_id=c.user_id and ro.role_key::text in('owner','super_admin'));
 end if;end;$$;
update greenloop_private.page_capability_installation set hash=(select md5(jsonb_agg(to_jsonb(c)order by page_key)::text)from greenloop_private.page_capability_catalog c)where identity='catalog';
create table if not exists greenloop_private.workflow_correction_audit(id uuid primary key default gen_random_uuid(),device_id uuid not null,actor uuid not null,changed_at timestamptz not null default now(),reason text not null,changes jsonb not null);
alter table greenloop_private.workflow_correction_audit enable row level security;revoke all on greenloop_private.workflow_correction_audit from public,anon,authenticated;
create or replace function greenloop_private.wf_audit_immutable()returns trigger language plpgsql as $$begin raise exception 'Workflow correction history is permanent.'using errcode='42501';end;$$;
drop trigger if exists workflow_correction_audit_immutable on greenloop_private.workflow_correction_audit;create trigger workflow_correction_audit_immutable before update or delete on greenloop_private.workflow_correction_audit for each row execute function greenloop_private.wf_audit_immutable();
create or replace function greenloop_private.wf_guard()returns void language plpgsql stable security definer set search_path=pg_catalog,public as $$begin perform greenloop_private.require_office_network();if greenloop_private.damage_tv_only(auth.uid())or not coalesce(public.has_page_capability_v1('reports','view'),false)or not coalesce(public.has_page_capability_v1('reports','workflow_correction'),false)then raise exception 'Full IMEI Workflow Correction access is required.'using errcode='42501';end if;end;$$;
create or replace function greenloop_private.wf_spec()returns jsonb language sql immutable set search_path=pg_catalog,public as $$select $spec$[{"kind":"device","label":"IMEI Entry","table":"public.devices","where":"d.id=$1","fields":["imei_1","brand","model","storage_gb","color","battery_health","battery_health_unavailable","device_platform","specification_region","original_grade","gc_grade","notes","created_at"],"key":"id","section":"IMEI Entry"},{"kind":"job","label":"Receiving / Ready Stock","table":"public.jobs","where":"d.device_id=$1 and d.deleted_at is null","fields":["supplier_id","receiving_batch_id","receiving_source","supplier_grade","purchase_cost","received_at","notes","customer_job_reference"],"key":"id","section":"Receiving / Ready Stock"},{"kind":"initial_qc","label":"Initial QC inspection","table":"public.initial_qc_inspections","where":"d.device_id=$1","fields":["overall_condition","cosmetic_condition","notes","work_required","inspected_by","inspected_at"],"key":"id","section":"Initial QC"},{"kind":"finding","label":"Initial QC finding / service","table":"public.initial_qc_findings","where":"exists(select 1 from public.initial_qc_inspections q where q.id=d.inspection_id and q.device_id=$1)","fields":["check_item","issue_found","action_required","department","priority","notes"],"key":"id","section":"Initial QC"},{"kind":"requirement","label":"Initial QC part requirement","table":"public.initial_qc_part_requirements","where":"d.device_id=$1","fields":["part_name","quantity_required","notes","identified_at"],"key":"id","section":"Initial QC"},{"kind":"work_order","label":"Work order","table":"public.job_work_orders","where":"d.device_id=$1","fields":["work_required","created_at"],"key":"id","section":"Lab & Glass"},{"kind":"step","label":"Technician assignment","table":"public.job_work_order_steps","where":"exists(select 1 from public.job_work_orders w where w.id=d.work_order_id and w.device_id=$1)","fields":["assigned_technician_roster_id","assigned_at","returned_at","created_at"],"key":"id","section":"Lab & Glass"},{"kind":"lab_work","label":"Laboratory work","table":"public.laboratory_work_records","where":"d.device_id=$1","fields":["assigned_at","started_at","paused_at","paused_seconds","completed_at","active_seconds","work_done","notes","result","material_cost"],"key":"id","section":"Lab & Glass"},{"kind":"glass_work","label":"Glass work","table":"public.glass_work_records","where":"d.device_id=$1","fields":["assigned_at","started_at","completed_at","work_done","material_cost","result","notes"],"key":"id","section":"Lab & Glass"},{"kind":"timer","label":"Technician recorded time","table":"public.technician_job_timers","where":"d.device_id=$1","fields":["technician_roster_id","started_at","stopped_at"],"key":"id","section":"Lab & Glass"},{"kind":"lab_service","label":"Lab service decision","table":"public.lab_service_reviews","where":"exists(select 1 from public.jobs j where j.id=d.job_id and j.device_id=$1 and j.deleted_at is null)","fields":["service_name","is_required","notes","reviewed_at"],"key":"id","section":"Lab & Glass"},{"kind":"lab_services","label":"Saved Lab & Glass services","table":"greenloop_private.lab_only_services","where":"exists(select 1 from public.jobs j where j.id=d.job_id and j.device_id=$1 and j.deleted_at is null)","fields":["names","saved_at","completed_at"],"key":"step_id","section":"Lab & Glass"},{"kind":"manual_part","label":"Recorded manual part","table":"public.lab_manual_part_installations","where":"d.device_id=$1","fields":["part_name","quantity","notes","installed_at"],"key":"id","section":"Parts"},{"kind":"part_order","label":"Parts order","table":"greenloop_private.parts_flow_orders","where":"d.device_id=$1","fields":["submitted_at"],"key":"id","section":"Parts"},{"kind":"part_request","label":"Ordered part","table":"public.job_part_requests","where":"d.device_id=$1","fields":["part_name","quantity_requested","notes","requested_at","requested_for_technician"],"key":"id","section":"Parts"},{"kind":"issue","label":"Issued part","table":"public.part_issue_transactions","where":"exists(select 1 from public.job_part_requests r where r.id=d.part_request_id and r.device_id=$1)","fields":["quantity_issued","issued_at","issue_notes","return_notes","unit_cost"],"key":"id","section":"Parts"},{"kind":"installation","label":"Installed part","table":"public.part_installations","where":"d.device_id=$1","fields":["quantity_installed","installed_at","notes","unit_cost"],"key":"id","section":"Parts"},{"kind":"part_price","label":"Parts price","table":"greenloop_private.parts_flow_prices","where":"exists(select 1 from greenloop_private.parts_flow_orders o where o.id=d.order_id and o.device_id=$1)","fields":["unit_price"],"key":"issue_id","section":"Parts"},{"kind":"part_return","label":"Returned part / Parts review","table":"greenloop_private.parts_flow_returns","where":"exists(select 1 from greenloop_private.parts_flow_orders o where o.id=d.order_id and o.device_id=$1)","fields":["quantity","notes","classification","requested_at","reviewed_at","review_notes"],"key":"id","section":"Parts"},{"kind":"legacy_return","label":"Recorded part return","table":"public.lab_part_return_requests","where":"d.device_id=$1","fields":["quantity","return_reason","requested_at","reviewed_at","review_notes"],"key":"id","section":"Parts"},{"kind":"final_qc","label":"Final QC","table":"public.final_qc_inspections","where":"d.device_id=$1","fields":["result","failure_department","failure_reason","notes","inspected_by","inspected_at","final_grade","final_battery_health","final_battery_health_unavailable","routed_to_frame"],"key":"id","section":"Final QC / Frame"},{"kind":"frame","label":"Frame result","table":"public.frame_department_results","where":"d.device_id=$1","fields":["result","notes","reviewed_by","reviewed_at"],"key":"id","section":"Final QC / Frame"},{"kind":"movement","label":"Department movement / Ready Stock time","table":"public.device_location_history","where":"d.device_id=$1","fields":["moved_at","movement_reason","notes"],"key":"id","section":"Receiving / Ready Stock"}]$spec$::jsonb;$$;
create or replace function greenloop_private.wf_rows(p_device uuid)returns table(kind text,row_key text,job_id uuid,data jsonb,revision text)language plpgsql stable security definer set search_path=pg_catalog,public as $$declare s jsonb;r jsonb;j uuid;key_sql text;begin
 for s in select value from jsonb_array_elements(greenloop_private.wf_spec())loop
  for r in execute 'select to_jsonb(d)from '||(s->>'table')||' d where '||(s->>'where')using p_device loop
   j:=nullif(r->>'job_id','')::uuid;
   if j is null then case s->>'kind'
    when 'job'then j:=(r->>'id')::uuid;
    when 'step'then select w.job_id into j from public.job_work_orders w where w.id=(r->>'work_order_id')::uuid;
    when 'finding'then select q.job_id into j from public.initial_qc_inspections q where q.id=(r->>'inspection_id')::uuid;
    when 'issue'then select q.job_id into j from public.job_part_requests q where q.id=(r->>'part_request_id')::uuid;
    when 'part_price'then select q.job_id into j from greenloop_private.parts_flow_orders q where q.id=(r->>'order_id')::uuid;
    else null;end case;end if;
   if j is not null and not exists(select 1 from public.jobs x where x.id=j and x.device_id=p_device and x.deleted_at is null)then continue;end if;
   kind:=s->>'kind';row_key:=case when kind='lab_services'then(r->>'job_id')||':'||(r->>'cycle')else r->>(s->>'key')end;job_id:=j;data:=r;revision:=md5(r::text);return next;
  end loop;
 end loop;
end;$$;
create or replace function greenloop_private.wf_fields(p_kind text,p_prices boolean)returns jsonb language sql stable security definer set search_path=pg_catalog,public as $$
 select coalesce(jsonb_agg(jsonb_build_object('key',f,'type',case when a.atttypid='bool'::regtype then 'boolean'when t.typtype='e'then 'enum'when t.typname in('int2','int4','int8','numeric','float4','float8')then 'number'when t.typname in('timestamp','timestamptz','date')then 'date'when t.typname='uuid'then 'choice'when t.typname='jsonb'then 'list'else 'text'end,'nullable',not a.attnotnull,'choices',case when t.typtype='e'then(select jsonb_agg(enumlabel order by enumsortorder)from pg_enum where enumtypid=t.oid)else null end)order by ord),'[]')
 from jsonb_array_elements(greenloop_private.wf_spec())s cross join lateral jsonb_array_elements_text(s->'fields')with ordinality x(f,ord)join pg_attribute a on a.attrelid=to_regclass(s->>'table')and a.attname=f and not a.attisdropped join pg_type t on t.oid=a.atttypid
 where s->>'kind'=p_kind and(p_prices or f not in('unit_cost','unit_price','purchase_cost','material_cost'));
$$;
create or replace function greenloop_private.wf_public_values(p_kind text,p_data jsonb,p_prices boolean)returns jsonb language sql stable security definer set search_path=pg_catalog,public as $$select coalesce(jsonb_object_agg(f->>'key',p_data->(f->>'key')),'{}')from jsonb_array_elements(greenloop_private.wf_fields(p_kind,p_prices))f;$$;
create or replace function public.get_full_imei_workflow_v1(p_identifier text)returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public as $$declare dev public.devices%rowtype;prices boolean;entries jsonb;result jsonb;begin
 perform greenloop_private.wf_guard();if p_identifier is null or length(btrim(p_identifier))not between 1 and 120 then raise exception 'Enter one IMEI or device number.'using errcode='22023';end if;
 select *into dev from public.devices d where d.deleted_at is null and(d.imei_1=btrim(p_identifier)or d.imei_2=btrim(p_identifier)or upper(d.device_number)=upper(btrim(p_identifier)))order by d.created_at desc limit 1;
 if dev.id is null then select d.*into dev from public.devices d join public.data_change_history h on h.device_id=d.id where d.deleted_at is null and(h.imei_before=btrim(p_identifier)or h.imei_after=btrim(p_identifier))order by h.changed_at desc limit 1;end if;
 if dev.id is null then raise exception 'No device was found.'using errcode='22023';end if;prices:=public.has_page_capability_v1('parts','view');
 select coalesce(jsonb_agg(jsonb_build_object('kind',r.kind,'row_key',r.row_key,'job_id',r.job_id,'job_number',(select job_number from public.jobs where id=r.job_id),'revision',r.revision,'values',greenloop_private.wf_public_values(r.kind,r.data,prices),'state',coalesce(r.data->>'current_status',r.data->>'status',r.data->>'step_status',r.data->>'result'),'context',coalesce(r.data->>'part_name',r.data->>'service_name',r.data->>'check_item',r.data->>'assigned_technician_name',(select q.part_name from public.job_part_requests q where q.id=(r.data->>'part_request_id')::uuid),(select q.part_name from public.part_issue_transactions i join public.job_part_requests q on q.id=i.part_request_id where i.id=coalesce((r.data->>'issue_id')::uuid,(r.data->>'id')::uuid)),r.data->>'model',case when r.data?'attempt_number'then 'Attempt '||(r.data->>'attempt_number')end,r.data->>'department',r.data->>'receiving_source',''),'label',s->>'label','section',s->>'section','fields',greenloop_private.wf_fields(r.kind,prices),'stock_source_required',r.kind='issue'and exists(select 1 from greenloop_private.parts_flow_stock ps where ps.inventory_id=(r.data->>'inventory_part_id')::uuid))order by ord,r.job_id,r.row_key),'[]')into entries from greenloop_private.wf_rows(dev.id)r join jsonb_array_elements(greenloop_private.wf_spec())with ordinality z(s,ord)on s->>'kind'=r.kind where prices or r.kind<>'part_price';
 select jsonb_build_object('device_id',dev.id,'device_number',dev.device_number,'imei',dev.imei_1,'status',dev.current_status,'snapshot',(select md5(coalesce(jsonb_agg(jsonb_build_array(kind,row_key,revision)order by kind,row_key),'[]')::text)from greenloop_private.wf_rows(dev.id)),'entries',entries,'prices_visible',prices,
 'options',jsonb_build_object('employees',coalesce((select jsonb_agg(jsonb_build_object('id',id,'label',full_name,'active',is_active)order by lower(full_name),id)from public.technician_roster),'[]'),'profiles',coalesce((select jsonb_agg(jsonb_build_object('id',id,'label',coalesce(full_name,login_username,'Staff'))order by full_name,id)from public.user_profiles),'[]'),'suppliers',coalesce((select jsonb_agg(jsonb_build_object('id',id,'label',supplier_code)order by supplier_code)from public.suppliers where deleted_at is null),'[]'),'batches',coalesce((select jsonb_agg(jsonb_build_object('id',id,'label',batch_number||coalesce(' / '||invoice_number,''))order by received_at desc,id)from public.receiving_batches),'[]')),
 'timeline',coalesce((select jsonb_agg(jsonb_build_object('title',e.event_title,'at',e.created_at,'actor',coalesce(p.full_name,'Staff'))order by e.created_at desc,e.id)from public.device_events e left join public.user_profiles p on p.id=e.actor_id where e.device_id=dev.id),'[]'),'history',coalesce((select jsonb_agg(jsonb_build_object('id',a.id,'changed_at',a.changed_at,'actor',coalesce(p.full_name,'Staff'),'reason',a.reason,'changes',case when prices then a.changes else(select coalesce(jsonb_agg(jsonb_build_object('kind',x->>'kind','row_key',x->>'row_key','before',greenloop_private.wf_public_values(x->>'kind',x->'before',false),'after',greenloop_private.wf_public_values(x->>'kind',x->'after',false))),'[]')from jsonb_array_elements(a.changes)x where x->>'kind'<>'part_price')end)order by a.changed_at desc,a.id)from greenloop_private.workflow_correction_audit a left join public.user_profiles p on p.id=a.actor where a.device_id=dev.id),'[]'))into result;return result;
end;$$;
create or replace function public.save_full_imei_workflow_v1(p_device_id uuid,p_snapshot text,p_changes jsonb,p_reason text,p_code text)returns jsonb language plpgsql security definer set search_path=pg_catalog,public as $$
declare dev public.devices%rowtype;item jsonb;row_before record;s jsonb;allowed text[];patch jsonb;keys text[];assignments text;key_expr text;work jsonb:='[]';entry jsonb;before_rows jsonb;after_rows jsonb;changes jsonb:='[]';audit_id uuid;before_movements jsonb;prices boolean;newval jsonb;oldval jsonb;jid uuid;req uuid;iss uuid;inv uuid;ledger uuid;delta integer;oldqty integer;newqty integer;oldclass text;newclass text;old_time timestamptz;stock_delta integer;affected uuid[]:='{}';cnt integer;old_imei text;fin public.final_qc_inspections%rowtype;latest_job public.jobs%rowtype;
begin
 perform greenloop_private.wf_guard();if p_code is distinct from '1213'then raise exception 'Incorrect correction code.'using errcode='42501';end if;if p_reason is null or length(btrim(p_reason))not between 5 and 2000 then raise exception 'Enter a correction reason from 5 to 2000 characters.'using errcode='22023';end if;
 if jsonb_typeof(p_changes)is distinct from 'array'or jsonb_array_length(p_changes)not between 1 and 1000 then raise exception 'Change at least one saved entry.'using errcode='22023';end if;
 perform pg_advisory_xact_lock(20420261026);perform pg_advisory_xact_lock(19920261026);
 perform 1 from public.jobs where device_id=p_device_id and deleted_at is null order by id for update;select *into dev from public.devices where id=p_device_id and deleted_at is null for update;if dev.id is null then raise exception 'The device is unavailable.'using errcode='22023';end if;old_imei:=dev.imei_1;prices:=public.has_page_capability_v1('parts','view');
 select coalesce(jsonb_agg(to_jsonb(x)order by kind,row_key),'[]')into before_rows from greenloop_private.wf_rows(dev.id)x;
 if p_snapshot is distinct from(select md5(coalesce(jsonb_agg(jsonb_build_array(kind,row_key,revision)order by kind,row_key),'[]')::text)from greenloop_private.wf_rows(dev.id))then raise exception 'This IMEI changed after it was loaded. Refresh before correcting it.'using errcode='40001';end if;
 if exists(select 1 from jsonb_array_elements(p_changes)x group by x->>'kind',x->>'row_key'having count(*)>1)then raise exception 'One entry was submitted twice.'using errcode='22023';end if;
 select jsonb_agg(id order by moved_at,id)into before_movements from public.device_location_history where device_id=dev.id;
 -- Resolve every target and allowed field before the first business write.
 for item in select value from jsonb_array_elements(p_changes)loop
  select *into row_before from greenloop_private.wf_rows(dev.id)where kind=item->>'kind'and row_key=item->>'row_key';if not found or row_before.revision is distinct from item->>'revision'then raise exception 'A selected entry is missing or has changed.'using errcode='40001';end if;
  select value into s from jsonb_array_elements(greenloop_private.wf_spec())where value->>'kind'=row_before.kind;
  patch:=item->'patch';select array_agg(value->>'key')into allowed from jsonb_array_elements(greenloop_private.wf_fields(row_before.kind,prices));
  if jsonb_typeof(patch)is distinct from 'object'or patch='{}'or exists(select 1 from jsonb_object_keys(patch)k where not k=any(allowed))or(row_before.kind='part_price'and not prices)then raise exception 'This correction contains an unavailable field.'using errcode='42501';end if;
  if exists(select 1 from jsonb_each(patch)e where jsonb_typeof(e.value)='string'and length(e.value#>>'{}')>6000)then raise exception 'A corrected value is too long.'using errcode='22023';end if;
  if row_before.kind='issue'and patch?'quantity_issued'and(patch->>'quantity_issued')::integer<>(row_before.data->>'quantity_issued')::integer and exists(select 1 from greenloop_private.parts_flow_stock where inventory_id=(row_before.data->>'inventory_part_id')::uuid)and coalesce(item->>'stock_handling','')not in('direct','inventory')then raise exception 'Select whether this issue used warehouse inventory or a directly supplied part.'using errcode='22023';end if;
  if patch?'names'and(jsonb_typeof(patch->'names')is distinct from 'array'or jsonb_array_length(patch->'names')>300 or exists(select 1 from jsonb_array_elements(patch->'names')v where jsonb_typeof(v)<>'string'or length(btrim(v#>>'{}'))not between 1 and 120))then raise exception 'Use one valid service name per line.'using errcode='22023';end if;
  if patch?'imei_1'and(patch->>'imei_1'!~'^[0-9]{15}$'or patch->>'imei_1'=dev.imei_2)then raise exception 'Use a unique 15-digit primary IMEI.'using errcode='22023';end if;
  if patch?'storage_gb'and(patch->>'storage_gb')::integer not between 1 and 16384 then raise exception 'Select valid storage in GB.'using errcode='22023';end if;
  if patch?'battery_health'and(patch->>'battery_health')::integer not between 0 and 100 or patch?'final_battery_health'and(patch->>'final_battery_health')::integer not between 0 and 100 then raise exception 'Battery health must be 0 to 100.'using errcode='22023';end if;
  if row_before.kind='device'and exists(select 1 from public.export_box_items where device_id=dev.id)and not public.has_page_capability_v1('reports','box_correction')then raise exception 'Box Correction permission is also required for device details already recorded in a box.'using errcode='42501';end if;
  newval:=row_before.data||patch;
  if newval?'started_at'and newval?'completed_at'and(newval->>'completed_at')::timestamptz<(newval->>'started_at')::timestamptz or newval?'assigned_at'and newval?'returned_at'and(newval->>'returned_at')::timestamptz<(newval->>'assigned_at')::timestamptz or newval?'started_at'and newval?'stopped_at'and(newval->>'stopped_at')::timestamptz<(newval->>'started_at')::timestamptz then raise exception 'Completion/return time cannot be earlier than its start/assignment.'using errcode='22023';end if;
  work:=work||jsonb_build_array(jsonb_build_object('kind',row_before.kind,'row_key',row_before.row_key,'spec',s,'before',row_before.data,'after',row_before.data||patch,'patch',patch,'stock_handling',item->>'stock_handling'));
 end loop;
 perform greenloop_private.begin_capability('save_full_imei_workflow_v1',jsonb_build_object('p_device_id',dev.id));perform greenloop_private.pf_context(true);
 for entry in select value from jsonb_array_elements(work)loop
  s:=entry->'spec';patch:=entry->'patch';oldval:=entry->'before';newval:=entry->'after';
  if entry->>'kind'='issue'and patch?'quantity_issued'and(newval->>'quantity_issued')::integer<(oldval->>'quantity_issued')::integer then patch:=patch-'quantity_issued';end if;
  if patch<>'{}'then
   select string_agg(format('%1$I=(select r.%1$I from jsonb_populate_record(null::%2$s,$1)r)',k,s->>'table'),','order by k)into assignments from jsonb_object_keys(patch)k;
   key_expr:=case when entry->>'kind'='lab_services'then '(d.job_id::text||'':''||d.cycle::text)'else format('d.%I::text',s->>'key')end;
   execute 'update '||(s->>'table')||' d set '||assignments||' where '||key_expr||'=$2'using oldval||patch,entry->>'row_key';
  end if;
  if entry->>'kind'='step'and patch?'assigned_technician_roster_id'and patch->'assigned_technician_roster_id'is distinct from oldval->'assigned_technician_roster_id'then
   if nullif(patch->>'assigned_technician_roster_id','')is not null and not exists(select 1 from public.technician_roster where id=(patch->>'assigned_technician_roster_id')::uuid and is_active)then raise exception 'Choose an active technician.'using errcode='22023';end if;
   update public.job_work_order_steps set assigned_technician_name=(select full_name from public.technician_roster where id=(patch->>'assigned_technician_roster_id')::uuid)where id=(entry->>'row_key')::uuid;
  end if;
  if entry->>'kind'='timer'then
   if patch?'technician_roster_id'and nullif(patch->>'technician_roster_id','')is not null and not exists(select 1 from public.technician_roster where id=(patch->>'technician_roster_id')::uuid and is_active)then raise exception 'Choose an active technician.'using errcode='22023';end if;
   update public.technician_job_timers set technician_name=coalesce((select full_name from public.technician_roster where id=technician_roster_id),case when patch?'technician_roster_id'then 'Unassigned'else technician_name end),elapsed_seconds=case when stopped_at is not null then greatest(0,extract(epoch from stopped_at-started_at)::integer)else elapsed_seconds end where id=(entry->>'row_key')::uuid;end if;
  if entry->>'kind'='job'and patch?'receiving_batch_id'and patch->'receiving_batch_id'is distinct from oldval->'receiving_batch_id'and nullif(patch->>'receiving_batch_id','')is not null then
   if not exists(select 1 from public.receiving_batches where id=(patch->>'receiving_batch_id')::uuid)then raise exception 'Choose a saved receiving batch.'using errcode='22023';end if;
   update public.jobs j set supplier_id=b.supplier_id from public.receiving_batches b where j.id=(entry->>'row_key')::uuid and b.id=j.receiving_batch_id;
   if exists(select 1 from public.receiving_batches b where b.id=(patch->>'receiving_batch_id')::uuid and b.planned_quantity is not null and b.planned_quantity<(select count(*)from public.jobs where receiving_batch_id=b.id and deleted_at is null))then raise exception 'This receiving batch has no remaining capacity.'using errcode='22023';end if;
  end if;
  if entry->>'kind'in('part_return','legacy_return')then
   if oldval->>'status'='approved'and (patch?'quantity'or patch?'classification'or patch?'return_reason'or patch?'reviewed_at'or patch?'review_notes')then
    oldqty:=(oldval->>'quantity')::integer;newqty:=(newval->>'quantity')::integer;oldclass:=case when entry->>'kind'='part_return'then oldval->>'classification'else oldval->>'return_reason'end;newclass:=case when entry->>'kind'='part_return'then newval->>'classification'else newval->>'return_reason'end;old_time:=(oldval->>'reviewed_at')::timestamptz;
    if newclass not in('not_needed','damaged','faulty','other')or newclass is null then raise exception 'Choose a valid reviewed return reason.'using errcode='22023';end if;
    if entry->>'kind'='part_return'then iss:=(oldval->>'issue_id')::uuid;else iss:=null;end if;
    select a.id,a.part_issue_id,a.inventory_part_id into ledger,iss,inv from public.part_return_audit a where a.device_id=dev.id and a.quantity=oldqty and a.returned_at=old_time and a.return_condition=case when oldclass='not_needed'then 'restocked'else oldclass end and(case when entry->>'kind'='part_return'then a.part_issue_id=(oldval->>'issue_id')::uuid else a.part_request_id=(oldval->>'part_request_id')::uuid end)order by a.id limit 1 for update;
    if ledger is null then raise exception 'The reviewed return ledger could not be matched. Nothing was saved.'using errcode='22023';end if;
    delta:=newqty-oldqty;update public.part_issue_transactions set quantity_returned=quantity_returned+delta where id=iss returning part_request_id into req;affected:=array_append(affected,req);
    stock_delta:=(case when newclass='not_needed'then newqty else 0 end)-(case when oldclass='not_needed'then oldqty else 0 end);
    if stock_delta<>0 then update public.part_inventory set stock_quantity=stock_quantity+stock_delta where id=inv and stock_quantity+stock_delta>=0;if not found then raise exception 'This return correction would overdraw inventory.'using errcode='22023';end if;end if;
    update public.part_return_audit set quantity=newqty,return_condition=case when newclass='not_needed'then 'restocked'else newclass end,reason=coalesce(nullif(newval->>'review_notes',''),newclass),returned_at=coalesce((newval->>'reviewed_at')::timestamptz,returned_at)where id=ledger;
   end if;
  end if;
  if entry->>'kind'='issue'then
   req:=(oldval->>'part_request_id')::uuid;affected:=array_append(affected,req);delta:=(newval->>'quantity_issued')::integer-(oldval->>'quantity_issued')::integer;inv:=(oldval->>'inventory_part_id')::uuid;
   if delta<>0 and(not exists(select 1 from greenloop_private.parts_flow_stock where inventory_id=inv)or entry->>'stock_handling'='inventory')then update public.part_inventory set stock_quantity=stock_quantity-delta where id=inv and stock_quantity-delta>=0;if not found then raise exception 'This issue correction would overdraw inventory.'using errcode='22023';end if;end if;
   if patch?'unit_cost'then update public.part_return_audit set unit_cost=(newval->>'unit_cost')::numeric where part_issue_id=(entry->>'row_key')::uuid;update public.part_installations set unit_cost=(newval->>'unit_cost')::numeric where part_issue_id=(entry->>'row_key')::uuid and not exists(select 1 from jsonb_array_elements(work)x where x->>'kind'='installation'and x->>'row_key'=public.part_installations.id::text and x->'patch'?'unit_cost');end if;
  elsif entry->>'kind'='installation'then affected:=array_append(affected,(oldval->>'part_request_id')::uuid);
  elsif entry->>'kind'='part_request'then affected:=array_append(affected,(entry->>'row_key')::uuid);
  end if;
 end loop;
 if exists(select 1 from public.jobs j join public.receiving_batches b on b.id=j.receiving_batch_id where j.device_id=dev.id and j.deleted_at is null and j.supplier_id is distinct from b.supplier_id)then raise exception 'Supplier code must match the selected Stock / Batch. Select the correct receipt together with its supplier.'using errcode='22023';end if;
 -- Apply issue reductions after matching return reductions, so row checks remain valid throughout.
 for entry in select value from jsonb_array_elements(work)where value->>'kind'='issue'loop
  update public.part_issue_transactions set quantity_issued=(entry->'after'->>'quantity_issued')::integer where id=(entry->>'row_key')::uuid;
 end loop;
 for req in select distinct unnest(affected)loop
  if exists(select 1 from public.job_part_requests r where r.id=req and r.quantity_requested<(select coalesce(sum(quantity_issued),0)from public.part_issue_transactions where part_request_id=req))then raise exception 'Ordered quantity cannot be less than the corrected issued quantity.'using errcode='22023';end if;
  if exists(select 1 from public.part_issue_transactions i where i.part_request_id=req and i.quantity_issued<i.quantity_returned+(select coalesce(sum(quantity_installed),0)from public.part_installations where part_issue_id=i.id)+(select coalesce(sum(quantity),0)from greenloop_private.parts_flow_returns where issue_id=i.id and status='pending'))then raise exception 'Issued quantity cannot be below installed, returned and pending-return quantities.'using errcode='22023';end if;
  if exists(select 1 from public.job_part_requests r join public.part_issue_transactions i on i.part_request_id=r.id join public.part_inventory p on p.id=i.inventory_part_id where r.id=req and greenloop_private.pp_key(r.part_name)<>greenloop_private.pp_key(p.part_name))then raise exception 'An issued part must keep its stock identity. Use its return and replacement workflow to change the physical part.'using errcode='22023';end if;
  update public.part_issue_transactions i set status=case when quantity_returned>=quantity_issued then 'returned'when quantity_returned>0 then 'partially_returned'else 'issued'end where part_request_id=req;
  update public.job_part_requests r set quantity_issued=(select coalesce(sum(quantity_issued),0)from public.part_issue_transactions where part_request_id=req),quantity_returned=(select coalesce(sum(quantity_returned),0)from public.part_issue_transactions where part_request_id=req),quantity_installed=(select coalesce(sum(quantity_installed),0)from public.part_installations where part_request_id=req)where id=req;
  update public.job_part_requests set status=case when status='cancelled'and quantity_issued=0 then status when quantity_installed>=quantity_requested then 'installed'when quantity_installed+quantity_returned>=quantity_requested then 'unused_returned'when quantity_installed>0 then 'partially_installed'when quantity_issued>=quantity_requested then 'issued'when quantity_issued>0 then 'partially_issued'else 'requested'end where id=req;
 end loop;
 if exists(select 1 from public.lab_part_return_requests r where r.device_id=dev.id and r.status='pending'and r.quantity>(select coalesce(sum(quantity_issued-quantity_returned),0)from public.part_issue_transactions where part_request_id=r.part_request_id))then raise exception 'A pending return exceeds the corrected issued balance.'using errcode='22023';end if;
 if before_movements is distinct from(select jsonb_agg(id order by moved_at,id)from public.device_location_history where device_id=dev.id)then raise exception 'Keep department movement dates in their existing order so repair cycles stay linked.'using errcode='22023';end if;
 for entry in select to_jsonb(x)from greenloop_private.wf_rows(dev.id)x loop
  newval:=entry->'data';if newval?'started_at'and newval?'completed_at'and(newval->>'completed_at')::timestamptz<(newval->>'started_at')::timestamptz or newval?'assigned_at'and newval?'returned_at'and(newval->>'returned_at')::timestamptz<(newval->>'assigned_at')::timestamptz or newval?'started_at'and newval?'stopped_at'and(newval->>'stopped_at')::timestamptz<(newval->>'started_at')::timestamptz then raise exception 'Completion/return time cannot be earlier than its start/assignment.'using errcode='22023';end if;
 end loop;
 select *into latest_job from public.jobs where device_id=dev.id and deleted_at is null order by received_at desc,created_at desc,id desc limit 1;
 select *into fin from public.final_qc_inspections where device_id=dev.id order by inspected_at desc,created_at desc,id desc limit 1;
 if latest_job.current_status::text in('qc_passed','production_pending','production_completed','ready_for_packing','ready_for_shipment')and(fin.id is null or fin.result::text<>'pass'or nullif(btrim(fin.final_grade),'')is null or exists(select 1 from public.job_part_requests where job_id=latest_job.id and status<>'cancelled'and quantity_requested>quantity_issued))then raise exception 'Ready Stock must retain a passed Final QC, final grade and completed parts requirement. Correct the linked records together; use Rework for new pending work.'using errcode='22023';end if;
 -- Keep denormalized box data coherent; normal box guards still apply.
 if exists(select 1 from jsonb_array_elements(work)x where x->>'kind'in('device','final_qc'))then
  if exists(select 1 from public.export_box_items where device_id=dev.id)and not public.has_page_capability_v1('reports','box_correction')then raise exception 'Box Correction access is required for a phone already in a box.'using errcode='42501';end if;
  update public.export_box_items b set imei=d.imei_1,model=d.model,storage_gb=d.storage_gb,color=d.color,final_grade=coalesce(fin.final_grade,d.gc_grade)from public.devices d where b.device_id=d.id and d.id=dev.id;
 end if;
 update greenloop_private.parts_flow_orders set revision=revision+1 where device_id=dev.id;
 update greenloop_private.lab_only_services l set revision=revision+1 where exists(select 1 from public.jobs j where j.id=l.job_id and j.device_id=dev.id);
 update greenloop_private.qc_work_usage_cache set built_at='-infinity' where singleton = true;
 select coalesce(jsonb_agg(to_jsonb(x)order by kind,row_key),'[]')into after_rows from greenloop_private.wf_rows(dev.id)x;
 for entry in select value from jsonb_array_elements(after_rows)loop
  select value into oldval from jsonb_array_elements(before_rows)x where x->>'kind'=entry->>'kind'and x->>'row_key'=entry->>'row_key';
  if greenloop_private.wf_public_values(entry->>'kind',oldval->'data',true)is distinct from greenloop_private.wf_public_values(entry->>'kind',entry->'data',true)then changes:=changes||jsonb_build_array(jsonb_build_object('kind',entry->>'kind','row_key',entry->>'row_key','before',greenloop_private.wf_public_values(entry->>'kind',oldval->'data',true),'after',greenloop_private.wf_public_values(entry->>'kind',entry->'data',true)));end if;
 end loop;
 if jsonb_array_length(changes)=0 then raise exception 'No values changed.'using errcode='22023';end if;
 insert into greenloop_private.workflow_correction_audit(device_id,actor,reason,changes)values(dev.id,auth.uid(),btrim(p_reason),changes)returning id into audit_id;
 insert into public.data_change_history(changed_by,device_id,job_id,device_number,job_number,imei_before,imei_after,change_reason,changed_fields,before_data,after_data)select auth.uid(),d.id,latest_job.id,d.device_number,latest_job.job_number,old_imei,d.imei_1,btrim(p_reason),jsonb_build_object('full_workflow',jsonb_build_object('old','Previous saved entries','new',jsonb_array_length(changes)||' linked entries corrected; audit '||audit_id)),'{}','{}'from public.devices d where d.id=dev.id;
 insert into public.device_events(device_id,job_id,event_type,event_title,event_data,actor_id)values(dev.id,latest_job.id,'full_workflow_corrected','Full IMEI workflow corrected in Reports',jsonb_build_object('audit_id',audit_id,'reason',btrim(p_reason),'entries',jsonb_array_length(changes)),auth.uid());
 if current_setting('greenloop.workflow_signal_tx',true)is distinct from txid_current()::text then update public.workflow_notification_signal set revision=revision+1 where id=1;perform set_config('greenloop.workflow_signal_tx',txid_current()::text,true);end if;
 perform greenloop_private.pf_context(false);perform greenloop_private.end_capability();return jsonb_build_object('saved',true,'audit_id',audit_id,'entries',jsonb_array_length(changes),'imei',(select imei_1 from public.devices where id=dev.id));
exception when others then raise;
end;$$;

insert into greenloop_private.capability_rpc_rules values('get_full_imei_workflow_v1','{"page":"reports","capability":"workflow_correction","read":true}'),('save_full_imei_workflow_v1','{"page":"reports","capability":"workflow_correction"}')on conflict(rpc_name)do update set rule=excluded.rule;
update greenloop_private.page_capability_installation set hash=(select md5(jsonb_agg(to_jsonb(r)order by rpc_name)::text)from greenloop_private.capability_rpc_rules r)where identity='rules';
do $wrap$declare f record;impl text;impl_identity text;args text;body text;begin
 for f in select p.*,pg_get_functiondef(p.oid)ddl,p.oid::regprocedure::text signature from pg_proc p where p.pronamespace='public'::regnamespace and p.proname in ('get_full_imei_workflow_v1','save_full_imei_workflow_v1')loop
 impl:='office_impl_'||f.oid;execute regexp_replace(f.ddl,'FUNCTION public\.'||f.proname||'\(','FUNCTION greenloop_private.'||impl||'(');impl_identity:='greenloop_private.'||impl||'('||oidvectortypes(f.proargtypes)||')';execute format('revoke all on function %s from public,anon,authenticated',impl_identity);select coalesce(string_agg('$'||i,','order by i),'')into args from generate_series(1,f.pronargs)i;
 body:=E'begin\n -- greenloop-office-wrapper-196\n perform greenloop_private.require_office_network();\n return greenloop_private.'||impl||'('||args||E');\nend;';execute format('create or replace function public.%I(%s)returns %s language plpgsql %s security definer set search_path=pg_catalog,public as %L',f.proname,pg_get_function_arguments(f.oid),pg_get_function_result(f.oid),case f.provolatile when 's'then 'stable'else 'volatile'end,body);execute format('revoke all on function %s from public,anon,authenticated',f.signature);execute format('grant execute on function %s to authenticated',f.signature);insert into greenloop_private.office_routines values(f.signature,impl_identity,md5(pg_get_functiondef(impl_identity::regprocedure)),md5(pg_get_functiondef(f.oid)))on conflict(identity)do update set implementation=excluded.implementation,original_hash=excluded.original_hash,wrapped_hash=excluded.wrapped_hash;
 end loop;
end;$wrap$;

do $$declare f record;begin for f in select oid::regprocedure::text identity from pg_proc where pronamespace='greenloop_private'::regnamespace and proname in('wf_guard','wf_spec','wf_rows','wf_fields','wf_public_values','wf_audit_immutable')loop execute format('revoke all on function %s from public,anon,authenticated',f.identity);end loop;end;$$;
create table if not exists greenloop_private.full_imei_workflow_installation(identity text primary key,hash text not null);alter table greenloop_private.full_imei_workflow_installation enable row level security;revoke all on greenloop_private.full_imei_workflow_installation from public,anon,authenticated;
insert into greenloop_private.full_imei_workflow_installation select p.oid::regprocedure::text,md5(pg_get_functiondef(p.oid))from pg_proc p where(p.pronamespace='public'::regnamespace and p.proname in('get_full_imei_workflow_v1','save_full_imei_workflow_v1'))or(p.pronamespace='greenloop_private'::regnamespace and p.proname in('wf_guard','wf_spec','wf_rows','wf_fields','wf_public_values','wf_audit_immutable'))or p.oid in(select to_regprocedure(r.implementation)from greenloop_private.office_routines r join pg_proc f on f.oid=to_regprocedure(r.identity)where f.proname in('get_full_imei_workflow_v1','save_full_imei_workflow_v1'))on conflict(identity)do update set hash=excluded.hash;
create or replace function public.get_full_imei_workflow_version()returns text language sql stable security definer set search_path=pg_catalog,public as $$select case when public.get_technician_parts_report_version()='20261029-technician-parts-1'and(select count(*)=10 and bool_and(coalesce(hash=md5(pg_get_functiondef(to_regprocedure(identity))),false))from greenloop_private.full_imei_workflow_installation)
 and exists(select 1 from greenloop_private.page_capability_catalog where page_key='reports'and capabilities @> '[{"key":"workflow_correction","write":true}]')
 and not exists(select 1 from unnest(array['workflow_correction_audit','full_imei_workflow_installation'])t where not exists(select 1 from pg_class where oid=to_regclass('greenloop_private.'||t)and relrowsecurity)or has_table_privilege('authenticated','greenloop_private.'||t,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE')or has_table_privilege('anon','greenloop_private.'||t,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE'))
 and not exists(select 1 from greenloop_private.full_imei_workflow_installation where identity like 'greenloop_private.%'and(has_function_privilege('authenticated',to_regprocedure(identity),'EXECUTE')or has_function_privilege('anon',to_regprocedure(identity),'EXECUTE')))
 and exists(select 1 from pg_trigger where tgrelid='greenloop_private.workflow_correction_audit'::regclass and tgname='workflow_correction_audit_immutable'and tgfoid='greenloop_private.wf_audit_immutable()'::regprocedure and tgenabled='O')then '20261029-full-imei-workflow-1'end;$$;
revoke all on function public.get_full_imei_workflow_version()from public;grant execute on function public.get_full_imei_workflow_version()to anon,authenticated;
do $$begin if public.get_full_imei_workflow_version()is distinct from '20261029-full-imei-workflow-1'then raise exception 'Full IMEI Workflow Correction verification failed.';end if;end;$$;
notify pgrst,'reload schema';commit;
select public.get_full_imei_workflow_version()as installed_full_imei_workflow_version;
